def sig_ir30():
    v = ret.rolling(30).std(); spx_v = ret['SPX'].rolling(30).std()
    return v.rolling(60).cov(spx_v)/spx_v.rolling(60).var()
def sig_ir20():
    v = ret.rolling(20).std(); spx_v = ret['SPX'].rolling(20).std()
    return v.rolling(30).cov(spx_v)/spx_v.rolling(30).var()
def sig_signe10():
    return (close/close.ewm(span=10).mean()-1.0).apply(np.sign)
def sig_xau_wti_ratio():
