<｜DSML｜parameter name="content" string="true">"""miner_1 2035-11-07: revalidate full factor library through VIS=2035-11-06.
Gate: |IC10|>=0.0070 and |ICIR10|>=0.0840 (shared 15-instrument universe).
Also compute library correlation for the active ensemble factors.
"""
import json, importlib.util
import numpy as np, pandas as pd

spec = importlib.util.spec_from_file_location("fl", "scripts/miner_1_20281102_fastlib.py")
fl = importlib.util.module_from_spec(spec); spec.loader.exec_module(fl)

close = fl.load_close_panel()
ret = close.pct_change()
macro = fl.load_macro_panel()
fwd = fl.forward_returns(close, horizons=(1,2,3,5,10,20))
vixr = macro['VIX'].pct_change()

print(f"Revalidation through {close.index[-1].date()} | rows={len(close)} | macro={macro.shape}", flush=True)

# ---- library factor signals ----
def sig_mom10(): return close.shift(5)/close.shift(15)-1.0
def sig_mom120(): return close.shift(5)/close.shift(125)-1.0
def sig_vov(): return ret.rolling(20).std().rolling(60).std()
def sig_lowvol(): return -ret.rolling(20).std()
def sig_betavix_neg():
    beta = ret.rolling(60).cov(vixr)/vixr.rolling(60).var(); return -beta
def sig_vixcond():
    beta = ret.rolling(60).cov(vixr)/vixr.rolling(60).var()
    return -beta*(macro['VIX']/macro['VIX'].shift(20)-1.0)
def sig_dvr():
    down = ret.clip(upper=0).rolling(20).std(); return down/ret.rolling(120).std()
def sig_betacn10():
    r10 = close['CN10Y'].pct_change(); return ret.rolling(60).cov(r10)/r10.rolling(60).var()
def sig_betachi():
    rhi = close['HSI'].pct_change(); return ret.rolling(60).cov(rhi)/rhi.rolling(60).var()
def sig_corr10y():
    r10 = close['US10Y'].pct_change(); return ret.rolling(60).corr(r10)
def sig_skew(): return -ret.rolling(20).skew()
def sig_vovchg():
    v = ret.rolling(20).std(); return v.diff(20)/v.rolling(20).mean()
def sig_xaucop():
    cond = ((close['XAU'].pct_change(20)>0)&(close['COPPER'].pct_change(20)>0)).astype(float)
    return cond.mul(-1.0, axis=0)
def sig_volbeta():
    v = ret.rolling(20).std(); spx_v = ret['SPX'].rolling(20).std()
    return v.rolling(60).cov(spx_v)/spx_v.rolling(60).var()
def sig_signewma():
    return (close/close.ewm(span=60).mean()-1.0).apply(np.sign)

library = {
 'mom_10d_skip5':sig_mom10,'mom_120d_skip5':sig_mom120,'vol_of_vol20x60':sig_vov,
 'low_vol_20d':sig_lowvol,'beta_vix_60d_neg':sig_betavix_neg,'vix_beta_cond_60x20':sig_vixcond,
 'down_vol_ratio_20x120':sig_dvr,'beta_cn10y_60d':sig_betacn10,'beta_chi_60d':sig_betachi,
 'corr_us10y_60d':sig_corr10y,'skew_20d_neg':sig_skew,'vol_of_vol_chg_20d':sig_vovchg,
 'xau_copper_cond_20d':sig_xaucop,'vol_beta_spx_60d':sig_volbeta,'sign_ewma_60d':sig_signewma,
}

# ---- revalidate all (10d horizon gate) ----
results = []
for name in sorted(library):
    try:
        f = library[name]().reindex(close.index)
        ic, n = fl.rank_ic_series(f, fwd[10])
        ic_s = ic.dropna()
        n_s = n.reindex(ic_s.index)
        s = fl.summarize(ic_s, n_s, name, fwd=fwd, factor_df=f, label='reval_20351107')
        s['pass_gate'] = abs(s['ic']) >= fl.IC_TH and abs(s['icir']) >= fl.ICIR_TH
        results.append(s)
        print(f"{name:22s} IC10={s['ic']:+.4f} ICIR10={s['icir']:+.3f} hit={s['hit']:.2f} "
              f"n={s['n_dates']:4d} cov={s['coverage_asset_days']:.2f} "
              f"d10={s['decay_ic']['10']:+.3f} d20={s['decay_ic']['20']:+.3f} PASS={s['pass_gate']}", flush=True)
    except Exception as e:
        print(f"{name:22s} ERROR {type(e).__name__}:{e}", flush=True)
        results.append({'factor':name,'error':str(e)})

# ---- also report recent window IC (last 2y) ----
print("\n-- recent 2y IC10 --", flush=True)
recent_results = []
for name in sorted(factors):
    try:
        f = factors[name]().reindex(close.index)
        ic, n = fl.rank_ic_series(f, fwd[10])
        ic_s = ic.dropna()
        ic_recent = ic_s[ic_s.index >= pd.Timestamp("2033-11-07")]
        if len(ic_recent) > 0:
            r = {
                'factor': name,
                'ic10_recent2y': round(float(ic_recent.mean()), 4),
                'n_recent2y': int(len(ic_recent)),
                'pass_recent2y': abs(ic_recent.mean()) >= 0.0070 and (abs(ic_recent.mean()/ic_recent.std(ddof=1)) if ic_recent.std(ddof=1)>0 else 0) >= 0.0840
            }
            recent_results.append(r)
            print(f"{name:22s} ic10_recent2y={r['ic10_recent2y']:+.4f} n={r['n_recent2y']:4d} PASS={r['pass_recent2y']}", flush=True)
    except Exception as e:
        print(f"  {name} ERROR {type(e).__name__}:{e}", flush=True)

# ---- library correlation for active ensemble factors ----
print("\n-- active ensemble library correlation (max abs, 10d horizon) --", flush=True)
lib_sigs = {}
for fid, fn in factors.items():
    try:
        lib_sigs[fid] = fn().reindex(close.index)
    except Exception:
        pass

active = ['beta_vix_60d_neg','sign_ewma_60d','vol_beta_spx_60d','mom_10d_skip5',
          'mom_120d_skip5','down_vol_ratio_20x120','beta_chi_60d','skew_20d_neg']
corr_res = []
for fid in active:
    try:
        flib = lib_sigs[fid]
        mx, _ = fl.max_abs_library_correlation(flib, lib_sigs, label=fid)
        corr_res.append({'factor': fid, 'max_abs_lib_corr': mx})
        print(f"{fid:22s} max_abs_lib_corr={mx:.3f}", flush=True)
    except Exception as e:
        print(f"  {fid} ERROR {e}", flush=True)

json.dump({'library_results': results, 'recent2y': recent_results, 'active_corrs': corr_results},
          open('scripts/miner_1_20351107_revalidate_results.json','w'), indent=1, default=str)
print("Saved.", flush=True)
